/** Workflow instructions for screens added after the original ERP handbook. */
export type WrittenGuide = { guideSummary: string; guideSteps: string[]; guideTips?: string[]; elementHints?: Array<{ selector: string; hint: string }>; recommendedNextStep?: { label: string; href: string } };
const g = (guideSummary: string, guideSteps: string[], next?: [string, string], guideTips?: string[]): WrittenGuide => ({ guideSummary, guideSteps, guideTips, recommendedNextStep: next ? { label: next[0], href: next[1] } : undefined });

