export const ROUTE_GUIDES: Record<string, WrittenGuide> = {
  "/finance/fx-revaluations": g("Review foreign obligation closing values and exact journal reversals.", ["Search a posted foreign invoice or supplier bill. Open the source to check its original accounting evidence.", "For a closing valuation, choose an open posting date, the closing rate in base currency per foreign unit, its evidence, and the applicable unrealised gain/loss accounts.", "Preview historical carrying value, translated value, prior valuation reversals and every journal leg. Replacement reverses the active valuation before posting the new value.", "Save a reason and evidence for independent approval. A different authorised accountant approves the frozen journal; stale evidence or a closed period stops posting.", "Use Reverse valuation for an active managed valuation. Legacy journal reversal accepts only an exact, attributed, balanced FX revaluation journal with one control and one profit/loss counterpart.", "In bank settlement, explicitly include valuation reversal in the preview. A partial settlement also reverses the full old valuation; review a new closing valuation for the remainder."], ["Bank settlement", "/finance/bank-recon"]),
  "/finance/legacy-fx": g("Reconcile legacy FX applications from original posted base-currency control evidence.", ["Search for the foreign-currency invoice or supplier bill and open its source record.", "Choose an open-period correction date and applicable realised FX accounts, then Preview historical reconciliation.", "Review the original carrying value, prior application releases, remaining balance and proposed correcting journal. Missing original base-currency journals or unresolved revaluations must be reconciled first.", "Enter the evidence reference and reason, then save for independent approval. A different accountant reviews the frozen evidence and approves/posts the shown correction.", "Return to Bank reconciliation and preview the remaining settlement. Changes or reversals of the approved evidence block further settlement until reconciled."], ["Bank reconciliation", "/finance/bank-recon"]),
  "/finance/input-vat": g("Review supplier VAT using finance-approved evidence and trace stock VAT into inventory, production and consumed costs.", ["Confirm the organisation's VAT recovery profile and approved schedule in tax settings. Leave unknown client policies pending.", "Search for the supplier bill. Split source VAT into directly recoverable, blocked and common input VAT; enter taxable and total turnover for common inputs.", "Enter the reason and evidence reference, then prepare the allocation. A different authorised approver must review the frozen amounts.", "Post the approved bill through the normal accounting flow. Editing the bill or tax policy invalidates the allocation and requires a new review.", "Keep the original invoice date. Choose the AP/tax accounting date and the cost allocation date explicitly; a later cost date requires the dedicated VAT cost clearing account and both open-period journals post atomically.", "For stock VAT, preview the traced remaining inventory, WIP, finished goods and consumed-cost destinations before saving for review. Mixed treatment needs explicit recovery per source line. New movements invalidate the cost preview.", "Use linked credit/debit corrections for capitalised documents. Generic financial-only voids and untraceable production reversals are blocked to preserve stock/GL reconciliation."], ["Tax definitions", "/finance/tax"]),
  "/settings": g("Find organisation settings by category and open the configuration your role may maintain.", ["Open the Settings hub from the ERP header.", "Choose the organisation, access, financial, tax, inventory or integration category relevant to the task.", "Read its linked tutorial before changing a setting that affects transactions or access.", "Review and save authorised changes, then verify a representative draft or read-only result."], ["ERP help centre", "/tutorial"]),
  "/inventory/quality": g("Contain stock-quality incidents, trace recalls and post only approved inventory losses.", ["Choose Quality hold, Loss or Recall and search for the affected lot.", "Verify product, warehouse and affected quantity, then enter the reason and evidence before opening the case.", "For a loss, have an authorised reviewer approve the value before Post approved loss. Check the resulting stock and accounting records.", "For recalls, follow the trace to affected deliveries and coordinate the operational response. Close with the required corrective and preventive action evidence."], ["Stock explorer", "/inventory/stock-explorer"]),
  "/pricing/workspace/commissions": g("Configure franchise SKU commission defaults for the network or a pricing zone.", ["Open Network defaults to review network-wide SKU commissions.", "Choose Zone defaults and the pricing zone to review its overrides.", "Review the effective hierarchy: outlet override, then zone default, then network default. These franchise price commissions are distinct from employee payroll earnings.", "Save the authorised changes and verify the effective outlet price before using it in an order."], ["Pricing overview", "/pricing/workspace/overview"]),
  "/settings/purchasing/receiving": g("Set supplier-invoice timing and QC-hold policy for incoming materials.", ["Open Receiving policy and review the current settings.", "Choose whether the supplier invoice is required before receiving. When it is not required, receipts and GRNI may precede the invoice.", "Review Hold lot-controlled materials for QC and confirm receiving warehouses support the required QC process.", "Save receiving policy with administrator permission and test a representative receipt before relying on the change."], ["Goods receipts", "/inventory/receipts"]),
  "/settings/coolcatch-readiness": g("Review seafood-template setup readiness before go-live.", ["Confirm the organisation named in the readiness report.", "Review template flags, master data, outlet and location checks.", "Open the source setup screens to resolve failed checks.", "Reload readiness and retain the result alongside operational acceptance evidence."], ["Settings", "/settings"]),
  "/settings/fmcg-setup": g("Prepare the FMCG organisation for operational and accounting cutover.", ["Confirm the organisation, official opening date and financial year-end.", "Review costing policy and the approved source closing balances for the day before opening.", "Complete warehouse, posting-account, tax and integration configuration using approved organisation details.", "Resolve the stock, AR/AP and GL reconciliation gates; record finance acceptance before activating official posting."], ["Period close", "/finance/period-close"]),
  "/settings/financial/posting-mappings": g("Map operational postings to approved chart-of-account codes.", ["Confirm the organisation and approved chart of accounts.", "Review inventory, WIP, finished goods, GRNI, tax and party-control mappings required by the enabled workflows.", "Select the correct active accounts and save with the appropriate settings permission.", "Verify representative postings in a test environment and reconcile their journal lines before operational use."], ["Chart of accounts", "/finance/chart-of-accounts"]),
  "/settings/environment": g("Review whether the organisation is operating in a test or live environment.", ["Verify the active organisation and environment banner.", "Inspect the available readiness and data-status controls.", "Use test data only within the designated sandbox and confirm the scope before any cleanup action.", "Follow the organisation's cutover approvals before switching official operation to live."], ["Operational setup", "/settings/fmcg-setup"]),
  "/settings/ops-runbook": g("Review operational jobs, recovery and retention controls.", ["Open the job or runbook relevant to the failed operation.", "Inspect scope, last outcome and the evidence or dry-run offered by the control.", "Use the authorised recovery action only after understanding whether it changes records.", "Verify the result in source records and the audit trail."], ["Audit log", "/settings/audit-log"]),
  "/settings/master-data-governance": g("Control who may change shared master data and how those changes are reviewed.", ["Confirm which system owns the product or party master for the organisation.", "Review existing governance and role rules before editing them.", "Limit catalogue maintenance to the designated ERP administrators and follow the available review process.", "Verify a permitted and a restricted user's access without sharing credentials."], ["Users and roles", "/settings/users-roles"]),
  "/settings/integrations/odaflow": g("Connect ERP to SFA while preserving catalogue ownership and matching.", ["Confirm the intended SFA organisation and the ERP organisation.", "Review connector status and configuration with the authorised administrator; keep credentials private.", "Resolve customer, product and unit matches before accepting orders.", "Verify one representative source order through the ERP review queue and check that retries do not duplicate it."], ["SFA order review", "/sales/odaflow-sync-queue"]),
  "/settings/sales/document-flow": g("Configure the sales document sequence used by this organisation.", ["Review the current order, delivery and invoicing policy.", "Choose only the sequence supported by your operational process and backend.", "Save with authorised settings access and review affected draft behaviour.", "Test a representative order through delivery and invoicing before relying on the change."], ["Sales orders", "/sales/orders"]),
  "/settings/inventory/costing": g("Configure the inventory valuation method and reconcile the opening cost basis.", ["Confirm the finance-approved valuation policy for the organisation.", "Review whether company-wide or warehouse-level costs are used by the enabled operations.", "Reconcile opening quantities, unit costs and the inventory GL before loading or activating valuation.", "Verify receipts, transfers, returns and production using the same policy."], ["Inventory valuation", "/inventory/valuation"]),
  "/settings/tax/vat-withholding": g("Configure VAT withholding treatment from approved tax and customer information.", ["Confirm the organisation's applicable withholding status and approved tax configuration with finance.", "Review eligible parties, mapping and effective settings on the page.", "Save with the required permission; keep statutory rates and classifications current through the authorised tax setup.", "Verify a representative transaction and its tax ledger and reports."], ["Tax and VAT", "/finance/tax"]),
  "/settings/display": g("Set how product names are displayed across the organisation.", ["Review the current product-name display preference.", "Select the offered display option and save with settings permission.", "Open a product list and a draft document to check readability.", "Confirm codes and identifiers still distinguish products with similar names."], ["Products", "/master/products"]),
  "/settings/sidebar": g("Organise the sidebar links without granting extra permissions.", ["Review the available sidebar sections and links.", "Use the offered ordering or visibility controls to suit the team's daily work.", "Save and reopen the sidebar to verify the arrangement.", "Use Users and roles for access changes; changing navigation does not authorise a restricted action."], ["Users and roles", "/settings/users-roles"]),
  "/manufacturing/capacity": g("Reserve finite production capacity against configured resources.", ["Review active resources, availability and the relevant production period.", "Choose the work order and inspect its routing and time requirements.", "Review proposed reservations and conflicts before committing the supported scheduling action.", "Recheck capacity when a batch is cancelled, completed or rescheduled."], ["Work orders", "/manufacturing/work-orders"]),
  "/manufacturing/trusted-devices": g("Manage trusted weighing devices and their production readings.", ["Review the device identity and authorised organisation scope.", "Use the offered registration controls only with the required administrator permission; keep device credentials private.", "Verify readings from the intended device and work order.", "Select an eligible reading during production completion. A typed reference is not proof that a trusted reading exists."], ["Work orders", "/manufacturing/work-orders"]),
  "/manufacturing/recipe-governance": g("Review recipe revisions and release an approved production formula.", ["Open the recipe revision and inspect its output unit, yield, ingredients and routing.", "Compare the proposed change with the currently effective recipe.", "Submit and approve through the offered governance actions with the required roles.", "Use the effective recipe to prepare new work orders; released batches retain their saved snapshots."], ["Recipes", "/manufacturing/boms"]),
  "/inventory/replenishment-policy": g("Set replenishment parameters by product and store.", ["Choose the product and warehouse covered by the policy.", "Review approved lead time, safety stock and ordering parameters.", "Save the policy with inventory administration permission.", "Run planning and inspect the resulting shortages and purchase suggestions before creating orders."], ["MRP", "/manufacturing/mrp"]),
  "/purchasing/match-policy": g("Configure approved purchase matching tolerances.", ["Review the applicable policy scope and effective settings.", "Enter finance-approved quantity and price tolerance values.", "Save with policy permission and test representative PO, receipt and bill matches.", "Investigate exceptions instead of raising tolerances to hide a discrepancy."], ["Three-way matching", "/ap/three-way-match"]),
  "/purchasing/exceptions": g("Resolve purchasing match exceptions using source evidence.", ["Open the blocked receipt or bill and read the variance findings.", "Compare PO quantity and price with the actual receipt and supplier bill.", "Correct the source error or follow the authorised exception-approval process with a reason.", "Re-run matching and inspect the final document and accounting status."], ["Three-way matching", "/ap/three-way-match"]),
  "/finance/fiscal-recovery": g("Recover uncertain fiscal signing attempts without issuing duplicate credits or invoices.", ["Locate the original document and fiscal attempt.", "Read provider status and source-value reservation evidence.", "Use the supported status check or recovery action for that attempt.", "Verify the final signed and posted result before retrying related documents."], ["Signing monitor", "/finance/kra-signing"]),
  "/finance/period-governance": g("Review controlled requests to reopen periods or waive specific close findings.", ["Open the request and inspect period, scope and reason.", "Review the supporting close findings and proposed effect.", "Approve or reject only with the authorised governance role.", "Verify the period state and retained audit evidence after the decision."], ["Period close", "/finance/period-close"]),
  "/finance/reporting-policy": g("Configure approved accounting classifications used by financial reports.", ["Review the chart of accounts and current report classifications.", "Map COGS, gross-margin and cash-flow categories using finance-approved treatment.", "Save through the supported policy workflow.", "Re-run reports and reconcile classifications and totals against the ledger."], ["Financial statements", "/finance/statements/pnl"]),
  "/projects/financials": g("Review project income, cost and budget evidence in the permitted scope.", ["Choose the project and financial period.", "Review posted source transactions and budget comparison.", "Investigate missing project assignments or classifications at source.", "Export or review the result only after the project balances reconcile."], ["Projects", "/projects/list"]),
  "/reports/snapshots": g("Reopen saved report evidence with its filters, generation time and source basis.", ["Search for a saved snapshot by report and date.", "Review its scope, filters and generation metadata.", "Open or download the stored result using the available controls.", "Generate a new report for current balances; a saved snapshot records its original point in time."], ["Report library", "/reports"]),
};

